def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _verify_oor_005() -> None:
    if not SOURCE_005.is_file():
        raise RuntimeError(f"Actual OOR-005 module missing: {SOURCE_005}")
    tree = ast.parse(SOURCE_005.read_text(encoding="utf-8"))
    names = {node.name for node in tree.body if isinstance(node, (ast.ClassDef, ast.FunctionDef))}
    required = {
        "OracleOperatorRuntimeSessionAuthorization",
        "OracleOperatorRuntimeSessionAuthorizationGate",
        "stable_hash",
    }
    missing = sorted(required - names)
    if missing:
        raise RuntimeError(f"OOR-005 contract incomplete: {missing}")


def _write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.lstrip(), encoding="utf-8", newline="\n")


def _update_init() -> None:
    if not RUNTIME_INIT.exists():
        _write(RUNTIME_INIT, "from __future__ import annotations\n")
    line = (
        "from qseries_v2.oracle_operator_runtime."
        "oracle_operator_runtime_session_authorization_consumption_gate import ("
        "OracleOperatorRuntimeSessionAuthorizationConsumption, "
        "OracleOperatorRuntimeSessionAuthorizationConsumptionGate, "
        "OracleOperatorRuntimeSessionAuthorizationConsumptionInvariantError)"
    )
    current = RUNTIME_INIT.read_text(encoding="utf-8")
    if line not in current:
        with RUNTIME_INIT.open("a", encoding="utf-8", newline="\n") as handle:
            if current and not current.endswith("\n"):
                handle.write("\n")
            handle.write(line + "\n")


def main() -> int:
    print("=" * 40)
    print(" OOR-006 INSTALLER")
    print(" ORACLE OPERATOR RUNTIME SESSION")
    print(" AUTHORIZATION CONSUMPTION GATE")
    print("=" * 40)
    try:
        _verify_oor_005()
        protected_hash = _sha256(SOURCE_005)
        print("[OK] Actual OOR-005 runtime session authorization contract verified")
        _write(PRODUCTION, PRODUCTION_SOURCE)
        _write(TEST, TEST_SOURCE)
        _update_init()
        print(f"[OK] FULL REPLACEMENT: {PRODUCTION}")
        print(f"[OK] FULL REPLACEMENT: {TEST}")
        print(f"[OK] PACKAGE UPDATED: {RUNTIME_INIT}")
        subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=True)
        if _sha256(SOURCE_005) != protected_hash:
            raise RuntimeError("Protected OOR-005 module changed during installation")
        print("[PASS] Protected OOR-005 module unchanged")
        print("[PASS] OOR-001 through OOR-005 lineage preserved")
        print("[DONE] OOR-006 INSTALLED AND VERIFIED")
        return 0
    except (RuntimeError, SyntaxError, subprocess.CalledProcessError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
